package android.os; import java.util.*; public class PowerManager { public static final int PARTIAL_WAKE_LOCK=1; public static boolean failAcquire; public static final ArrayList<WakeLock> locks=new ArrayList<>(); public WakeLock newWakeLock(int level,String tag){if(level!=PARTIAL_WAKE_LOCK)throw new AssertionError("wrong lock");WakeLock w=new WakeLock();locks.add(w);return w;} public static class WakeLock { public boolean held,ref; public long timeout,until; public void setReferenceCounted(boolean v){ref=v;} public void acquire(long timeout){if(failAcquire)throw new SecurityException("sensitive system error"); if(timeout<=0)throw new AssertionError("unbounded lock");this.timeout=timeout;until=SystemClock.now+timeout;held=true;} public boolean isHeld(){return held&&SystemClock.now<until;} public void release(){held=false;} } public static long heldCount(){return locks.stream().filter(WakeLock::isHeld).count();} public static void reset(){locks.clear();failAcquire=false;} }